type BST = Leaf | Node(BST, int, BST)

pure func insert(tree: BST, val: int) -> BST =
  match tree {
    Leaf => Node(Leaf, val, Leaf),
    Node(l, v, r) =>
      if val < v then Node(insert(l, val), v, r)
      else if val > v then Node(l, v, insert(r, val))
      else Node(l, v, r)
  }

pure func contains(tree: BST, val: int) -> bool =
  match tree {
    Leaf => false,
    Node(l, v, r) =>
      if val == v then true
      else if val < v then contains(l, val)
      else contains(r, val)
  }

pure func size(tree: BST) -> int =
  match tree {
    Leaf => 0,
    Node(l, v, r) => 1 + size(l) + size(r)
  }

pure func isBST(tree: BST, lo: int, hi: int) -> bool =
  match tree {
    Leaf => true,
    Node(l, v, r) =>
      v > lo && v < hi && isBST(l, lo, v) && isBST(r, v, hi)
  }

pure func insertPreservesBST(val: int) -> bool =
  isBST(insert(Leaf, val), -999999, 999999)

pure func insertThenFind(val: int) -> bool =
  contains(insert(Leaf, val), val)

export func main() -> () ! {IO} {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

