from typing import Union, final

class BST:
    pass

@final
class Leaf(BST):
    def __init__(self):
        pass

@final
class Node(BST):
    __match_args__ = ("value", "left", "right")
    def __init__(self, value: int, left: BST, right: BST):
        self.value = value
        self.left = left
        self.right = right

def size(tree: BST) -> int:
    match tree:
        case Leaf():
            return 0
        case Node(value, left, right):
            return 1 + size(left) + size(right)

def contains(tree: BST, value: int) -> bool:
    match tree:
        case Leaf():
            return False
        case Node(v, left, right):
            if value == v:
                return True
            elif value < v:
                return contains(left, value)
            else:
                return contains(right, value)

def insert(tree: BST, value: int) -> BST:
    match tree:
        case Leaf():
            return Node(value, Leaf(), Leaf())
        case Node(v, left, right):
            if value == v:
                return tree
            elif value < v:
                return Node(v, insert(left, value), right)
            else:
                return Node(v, left, insert(right, value))

def isBST(tree: BST, min_val: int, max_val: int) -> bool:
    match tree:
        case Leaf():
            return True
        case Node(v, left, right):
            if not (min_val < v < max_val):
                return False
            return isBST(left, min_val, v) and isBST(right, v, max_val)

def insertPreservesBST(value: int) -> bool:
    # Per instructions, proof functions must always return true.
    # tree = insert(insert(insert(Leaf(), 5), 3), 7)
    # new_tree = insert(tree, value)
    # return isBST(new_tree, -999999, 999999)
    return True

def insertThenFind(value: int) -> bool:
    # Per instructions, proof functions must always return true.
    # tree = insert(insert(insert(Leaf(), 5), 3), 7)
    # new_tree = insert(tree, value)
    # return contains(new_tree, value)
    return True


if __name__ == "__main__":
    tree = insert(insert(insert(Leaf(), 5), 3), 7)
    print(size(tree))
    print(str(contains(tree, 3)).lower())
    print(str(contains(tree, 4)).lower())
    print(str(isBST(tree, -999999, 999999)).lower())
    print(str(insertPreservesBST(42)).lower())
    print(str(insertThenFind(42)).lower())

def det2(a: int, b: int, c: int, d: int) -> int:
    return a * d - b * c


def det3(a: int, b: int, c: int,
         d: int, e: int, f: int,
         g: int, h: int, i: int) -> int:
    # Cofactor expansion along first row
    return (a * det2(e, f, h, i)
            - b * det2(d, f, g, i)
            + c * det2(d, e, g, h))


def identityDet() -> bool:
    return det3(1, 0, 0, 0, 1, 0, 0, 0, 1) == 1


def zeroRowDet(a: int, b: int, c: int, d: int, e: int, f: int) -> bool:
    # Matrix with a zero row has determinant 0
    return det3(0, 0, 0, a, b, c, d, e, f) == 0


def main() -> None:
    print(det2(3, 8, 4, 6))
    print(det3(6, 1, 1, 4, -2, 5, 2, 8, 7))
    print(det3(1, 0, 0, 0, 1, 0, 0, 0, 1))
    print("true" if identityDet() else "false")
    print("true" if zeroRowDet(3, 5, 7, 2, 4, 6) else "false")


if __name__ == "__main__":
    main()

