module benchmark/solution
import std/string (chars, stringToInt)

-- Repeat a character string n times
func repeatChar(c: string, n: int) -> string =
  if n <= 0 then ""
  else "${c}${repeatChar(c, n - 1)}"

-- Encode helper: processes remaining chars with current run state
func encodeHelper(cs: [string], current: string, count: int, acc: string) -> string =
  match cs {
    [] => "${acc}${show(count)}${current}",
    c :: rest =>
      if c == current
      then encodeHelper(rest, current, count + 1, acc)
      else encodeHelper(rest, c, 1, "${acc}${show(count)}${current}")
  }

-- Encode: "aaabbc" -> "3a2b1c"
func encode(s: string) -> string =
  match chars(s) {
    [] => "",
    c :: rest => encodeHelper(rest, c, 1, "")
  }

-- Check if a single-char string is a digit
func isDigit(c: string) -> bool =
  c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
  c == "5" || c == "6" || c == "7" || c == "8" || c == "9"

-- Decode helper: processes chars accumulating digit string then repeating char
func decodeHelper(cs: [string], numAcc: string, strAcc: string) -> string =
  match cs {
    [] => strAcc,
    c :: rest =>
      if isDigit(c)
      then decodeHelper(rest, "${numAcc}${c}", strAcc)
      else
        match stringToInt(numAcc) {
          Some(n) => decodeHelper(rest, "", "${strAcc}${repeatChar(c, n)}"),
          None => decodeHelper(rest, "", strAcc)
        }
  }

-- Decode: "3a2b1c" -> "aaabbc"
func decode(s: string) -> string =
  decodeHelper(chars(s), "", "")

-- Proof: decode(encode(s)) == s
func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

-- Proof: encode of single char c is "1c"
func singleCharEncode(c: string) -> bool =
  encode(c) == "1${c}"

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(show(singleCharEncode("q")))
}

