import std/string (startsWith, substring, length)

pure func toRoman(n: int) -> string {
  if n <= 0 then ""
  else if n >= 1000 then "M${toRoman(n - 1000)}"
  else if n >= 900 then "CM${toRoman(n - 900)}"
  else if n >= 500 then "D${toRoman(n - 500)}"
  else if n >= 400 then "CD${toRoman(n - 400)}"
  else if n >= 100 then "C${toRoman(n - 100)}"
  else if n >= 90 then "XC${toRoman(n - 90)}"
  else if n >= 50 then "L${toRoman(n - 50)}"
  else if n >= 40 then "XL${toRoman(n - 40)}"
  else if n >= 10 then "X${toRoman(n - 10)}"
  else if n >= 9 then "IX${toRoman(n - 9)}"
  else if n >= 5 then "V${toRoman(n - 5)}"
  else if n >= 4 then "IV${toRoman(n - 4)}"
  else if n >= 1 then "I${toRoman(n - 1)}"
  else ""
}

pure func fromRoman(s: string) -> int {
  if s == "" then 0
  else if startsWith(s, "CM") then 900 + fromRoman(substring(s, 2, length(s)))
  else if startsWith(s, "CD") then 400 + fromRoman(substring(s, 2, length(s)))
  else if startsWith(s, "XC") then 90 + fromRoman(substring(s, 2, length(s)))
  else if startsWith(s, "XL") then 40 + fromRoman(substring(s, 2, length(s)))
  else if startsWith(s, "IX") then 9 + fromRoman(substring(s, 2, length(s)))
  else if startsWith(s, "IV") then 4 + fromRoman(substring(s, 2, length(s)))
  else if startsWith(s, "M") then 1000 + fromRoman(substring(s, 1, length(s)))
  else if startsWith(s, "D") then 500 + fromRoman(substring(s, 1, length(s)))
  else if startsWith(s, "C") then 100 + fromRoman(substring(s, 1, length(s)))
  else if startsWith(s, "L") then 50 + fromRoman(substring(s, 1, length(s)))
  else if startsWith(s, "X") then 10 + fromRoman(substring(s, 1, length(s)))
  else if startsWith(s, "V") then 5 + fromRoman(substring(s, 1, length(s)))
  else if startsWith(s, "I") then 1 + fromRoman(substring(s, 1, length(s)))
  else 0
}

pure func roundtrip(n: int) -> bool {
  fromRoman(toRoman(n)) == n
}

pure func distinctEncoding(a: int, b: int) -> bool {
  toRoman(a) != toRoman(b)
}

