module benchmark/solution

type SortedSet = SNil | SCons(int, SortedSet)

pure func sLength(s: SortedSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

pure func isSorted(s: SortedSet) -> bool =
  match s {
    SNil => true,
    SCons(_, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

pure func sMerge(a: SortedSet, b: SortedSet) -> SortedSet =
  match a {
    SNil => b,
    SCons(x, restA) => match b {
      SNil => a,
      SCons(y, restB) =>
        if x < y then SCons(x, sMerge(restA, b))
        else if x > y then SCons(y, sMerge(a, restB))
        else SCons(x, sMerge(restA, restB))
    }
  }

pure func sIntersect(a: SortedSet, b: SortedSet) -> SortedSet =
  match a {
    SNil => SNil,
    SCons(x, restA) => match b {
      SNil => SNil,
      SCons(y, restB) =>
        if x < y then sIntersect(restA, b)
        else if x > y then sIntersect(a, restB)
        else SCons(x, sIntersect(restA, restB))
    }
  }

pure func toStrHelper(s: SortedSet, first: bool) -> string =
  match s {
    SNil => "",
    SCons(x, rest) =>
      if first then "${show(x)}${toStrHelper(rest, false)}"
      else ",${show(x)}${toStrHelper(rest, false)}"
  }

pure func toStr(s: SortedSet) -> string =
  "[${toStrHelper(s, true)}]"

pure func mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool =
  isSorted(sMerge(a, b))

pure func inclusionExclusion(a: SortedSet, b: SortedSet) -> bool =
  sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

