from __future__ import annotations
from dataclasses import dataclass
from typing import Union


@dataclass
class SNil:
    pass


@dataclass
class SCons:
    head: int
    tail: SortedSet


SortedSet = Union[SNil, SCons]


def toStr(s: SortedSet) -> str:
    elements = []
    cur = s
    while isinstance(cur, SCons):
        elements.append(str(cur.head))
        cur = cur.tail
    return "[" + ",".join(elements) + "]"


def sLength(s: SortedSet) -> int:
    count = 0
    cur = s
    while isinstance(cur, SCons):
        count += 1
        cur = cur.tail
    return count


def isSorted(s: SortedSet) -> bool:
    if isinstance(s, SNil):
        return True
    cur = s
    while isinstance(cur, SCons) and isinstance(cur.tail, SCons):
        if cur.head >= cur.tail.head:
            return False
        cur = cur.tail
    return True


def sMerge(a: SortedSet, b: SortedSet) -> SortedSet:
    if isinstance(a, SNil):
        return b
    if isinstance(b, SNil):
        return a
    if a.head < b.head:
        return SCons(a.head, sMerge(a.tail, b))
    elif a.head > b.head:
        return SCons(b.head, sMerge(a, b.tail))
    else:  # equal: include once, advance both
        return SCons(a.head, sMerge(a.tail, b.tail))


def sIntersect(a: SortedSet, b: SortedSet) -> SortedSet:
    if isinstance(a, SNil) or isinstance(b, SNil):
        return SNil()
    if a.head == b.head:
        return SCons(a.head, sIntersect(a.tail, b.tail))
    elif a.head < b.head:
        return sIntersect(a.tail, b)
    else:
        return sIntersect(a, b.tail)


def mergePreservesSorted(a: SortedSet, b: SortedSet) -> bool:
    return isSorted(sMerge(a, b))


def inclusionExclusion(a: SortedSet, b: SortedSet) -> bool:
    return sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)


def main():
    a = SCons(1, SCons(3, SCons(5, SNil())))
    b = SCons(2, SCons(3, SCons(4, SNil())))

    print(toStr(sMerge(a, b)))
    print(toStr(sIntersect(a, b)))
    print(sLength(sMerge(a, b)))
    print("true" if isSorted(sMerge(a, b)) else "false")
    print("true" if mergePreservesSorted(a, b) else "false")
    print("true" if inclusionExclusion(a, b) else "false")


if __name__ == "__main__":
    main()

