import std/option (Option, Some, None)
import std/math (intToFloat)

type UserRow = UserRow({name: string, age: int, email: string})

pure func parseRow(cols: [string]) -> Option[UserRow] =
  match cols {
    name :: ageStr :: email :: _ =>
      let n = trim(name) in
      let a = trim(ageStr) in
      let e = trim(email) in
      match stringToInt(a) {
        None => None,
        Some(age) =>
          if age <= 0 then None
          else if not contains(e, "@") then None
          else Some(UserRow({name: n, age: age, email: e}))
      },
    _ => None
  }

func rowToJson(row: UserRow) -> Json =
  match row {
    UserRow({name, age, email}) =>
      jo([kv("name", js(name)), kv("age", jnum(intToFloat(age))), kv("email", js(email))])
  }

