type Term = TVar(string) | TLam(string, Term) | TApp(Term, Term)

pure func subst(term: Term, var: string, replacement: Term) -> Term =
  match term {
    TVar(name) => if name == var then replacement else TVar(name),
    TLam(param, body) => if param == var then TLam(param, body) else TLam(param, subst(body, var, replacement)),
    TApp(f, arg) => TApp(subst(f, var, replacement), subst(arg, var, replacement))
  }

pure func eval(term: Term) -> Term =
  match term {
    TVar(name) => TVar(name),
    TLam(param, body) => TLam(param, body),
    TApp(f, arg) => {
      let ef = eval(f);
      let ea = eval(arg);
      match ef {
        TLam(param, body) => eval(subst(body, param, ea)),
        _ => TApp(ef, ea)
      }
    }
  }

pure func showTerm(term: Term) -> string =
  match term {
    TVar(name) => name,
    TLam(param, body) => "λ${param}.${showTerm(body)}",
