from dataclasses import dataclass
from typing import Any

@dataclass
class Num:
    value: int

@dataclass
class Var:
    name: str

@dataclass
class Add:
    left: Any
    right: Any

@dataclass
class Mul:
    left: Any
    right: Any

@dataclass
class Let:
    name: str
    expr: Any
    body: Any

def lookup(name, env):
    for n, v in reversed(env):
        if n == name:
            return v
    raise NameError(f"Unbound variable: {name}")

def eval(expr, env):
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, e1, e2):
            val = eval(e1, env)
            return eval(e2, env + [(name, val)])

def main():
    program = Let("x", Num(5), Let("y", Add(Var("x"), Num(3)), Mul(Var("x"), Var("y"))))
    result = eval(program, [])
