pure func balance(color: Color, left: RBTree, value: int, right: RBTree) -> RBTree =
  match color {
    Black => match left {
      Node(Red, Node(Red, a, x, b), y, c) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c, value, right)),
      Node(Red, a, x, Node(Red, b, y, c)) =>
        Node(Red, Node(Black, a, x, b), y, Node(Black, c, value, right)),
