from dataclasses import dataclass
from typing import Generic, TypeVar

# Define the Algebraic Data Types (ADTs) for State, Event, and Result.
# Using the `|` syntax for unions, available in Python 3.10+

# --- State ADT ---
@dataclass
class Idle:
    pass

@dataclass
class HasCredit:
    cents: int

@dataclass
class Dispensing:
    change: int

State = Idle | HasCredit | Dispensing

# --- Event ADT ---
@dataclass
class Insert:
    cents: int

@dataclass
class Select:
    code: int

@dataclass
class DispenseDone:
    pass

Event = Insert | Select | DispenseDone

# --- Result ADT (Generic) ---
T = TypeVar('T')
E = TypeVar('E')

@dataclass
class Ok(Generic[T]):
    value: T

@dataclass
class Err(Generic[E]):
    reason: E

Result = Ok[State] | Err[str]

# --- Vending Machine Logic ---

PRICES = {1: 125, 2: 75, 3: 100}

def step(state: State, event: Event) -> Result:
    """
    Performs a single state transition based on the current state and event.
    Returns Ok(NewState) on success or Err(reason) on failure.
    """
    match (state, event):
        # Transitions from Idle state
        case Idle(), Insert(n):
            return Ok(HasCredit(n))
        case Idle(), Select(_):
            return Err("no_credit")
        case Idle(), DispenseDone():
            return Err("not_dispensing")

        # Transitions from HasCredit state
        case HasCredit(c), Insert(n):
            return Ok(HasCredit(c + n))
        case HasCredit(c), Select(code):
            if code not in PRICES:
                return Err("unknown_item")
            price = PRICES[code]
            if c < price:
                return Err("insufficient_funds")
            return Ok(Dispensing(c - price))
        case HasCredit(_), DispenseDone():
            return Err("not_dispensing")

        # Transitions from Dispensing state
        case Dispensing(_), Insert(_):
            return Err("busy")
        case Dispensing(_), Select(_):
            return Err("busy")
        case Dispensing(_), DispenseDone():
            return Ok(Idle())

    # This line should be unreachable if all state/event pairs are handled.
    # It acts as a fallback for exhaustive checking.
    raise TypeError("Unhandled state/event combination")


def main():
    """
    Runs the vending machine simulation with a predefined sequence of events.
    """
    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    state: State = Idle()

    for event in events:
        result = step(state, event)

        match result:
            case Ok(new_state):
                state = new_state
                # Print the outcome of a successful transition
                match new_state:
                    case Idle():
                        print("ok: IDLE")
                    case HasCredit(n):
                        print(f"ok: CREDIT({n})")
                    case Dispensing(ch):
                        print(f"ok: DISPENSING({ch})")
            case Err(reason):
                # Print the reason for a failed transition
                print(f"err: {reason}")

if __name__ == "__main__":
    main()

