module benchmark/solution

type Expr = Const(int) | Var(string) | Add(Expr, Expr) | Mul(Expr, Expr)

pure func diff(expr: Expr, var: string) -> Expr =
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == var then Const(1) else Const(0),
    Add(f, g) => Add(diff(f, var), diff(g, var)),
    Mul(f, g) => Add(Mul(f, diff(g, var)), Mul(g, diff(f, var)))
  }

pure func simplify(expr: Expr) -> Expr =
  match expr {
    Add(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => sb,
        (_, Const(0)) => sa,
        _ => Add(sa, sb)
      }
    },
    Mul(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match (sa, sb) {
        (Const(0), _) => Const(0),
        (_, Const(0)) => Const(0),
        (Const(1), _) => sb,
        (_, Const(1)) => sa,
        _ => Mul(sa, sb)
      }
    },
    _ => expr
  }

pure func showExpr(expr: Expr) -> string =
  match expr {
    Const(n) => show(n),
    Var(name) => name,
    Add(a, b) => "(${showExpr(a)} + ${showExpr(b)})",
    Mul(a, b) => "(${showExpr(a)} * ${showExpr(b)})"
  }

