module benchmark/solution

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type Subst = [(string, Type)]

type UnifyResult = Success(Subst) | Fail

pure func apply(subst: Subst, t: Type) -> Type =
  match t {
    TInt => TInt,
    TBool => TBool,
    TVar(name) => lookupSubst(subst, name, t),
    TFunc(arg, res) => TFunc(apply(subst, arg), apply(subst, res))
  }

pure func lookupSubst(subst: Subst, name: string, default: Type) -> Type =
  match subst {
    [] => default,
    (k, v) :: rest => if k == name then v else lookupSubst(rest, name, default)
  }

pure func unify(t1: Type, t2: Type) -> UnifyResult =
  match t1 {
    TInt => match t2 {
      TInt => Success([]),
      TVar(a) => Success([(a, TInt)]),
      _ => Fail
    },
    TBool => match t2 {
      TBool => Success([]),
      TVar(a) => Success([(a, TBool)]),
      _ => Fail
    },
    TVar(a) => Success([(a, t2)]),
    TFunc(a1, r1) => match t2 {
      TFunc(a2, r2) => match unify(a1, a2) {
        Fail => Fail,
        Success(s1) => match unify(r1, r2) {
          Fail => Fail,
          Success(s2) => Success(s1 ++ s2)
        }
      },
      TVar(a) => Success([(a, t1)]),
      _ => Fail
    }
  }

pure func showType(t: Type) -> string =
  match t {
    TInt => "TInt",
    TBool => "TBool",
    TVar(name) => "TVar(${name})",
    TFunc(arg, res) => "TFunc(${showType(arg)}, ${showType(res)})"
  }

pure func lookupVar(subst: Subst, name: string) -> string =
  match subst {
    [] => "not found",
    (k, v) :: rest => if k == name then showType(v) else lookupVar(rest, name)
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Fail => println("unification failed"),
    Success(subst) => {
      println("a = ${lookupVar(subst, "a")}");
      println("b = ${lookupVar(subst, "b")}")
    }
  }
}

