import std/option (Option, Some, None)

pure func safeDiv(a: int, b: int) -> Option[int] =
  if b == 0 then None else Some(a / b)

pure func safeSqrt(x: int) -> Option[int] =
  if x < 0 then None else Some(floatToInt(sqrt(intToFloat(x))))

pure func optFlatMap(opt: Option[int], f: int -> Option[int]) -> Option[int] =
  match opt {
    None => None,
    Some(x) => f(x)
  }

pure func optMap(opt: Option[int], f: int -> int) -> Option[int] =
